+            return new RemoteClusterClientBootstrapOptions(
+                tcpNoDelay,
+                tcpKeepAlive,
+                tcpKeepIdle,
+                tcpKeepInterval,
+                tcpKeepCount,
+                tcpSendBufferSize,
+                tcpReceiveBufferSize,
+                tcpReuseAddress
