+
+    @Override
+    protected ExplainIndexDataLifecycle mutateInstance(ExplainIndexDataLifecycle instance) throws IOException {
+        return createManagedIndexDLMExplanation(System.nanoTime(), randomBoolean() ? new DataLifecycle() : null);
